// Official Emblem of I.E.P.M. N° 24009 "TÚPAC AMARU II" - PUQUIO
export const SCHOOL_LOGO_PNG_BASE64 = "data:image/png;base64,";
export const SCHOOL_LOGO_PATH = "/assets/logo-tupac-amaru.png";
export const SCHOOL_LOGO_SVG_PATH = "/assets/logo-tupac-amaru.svg";

// Safe helper to get the active institutional logo (localStorage or default)
export function getActiveSchoolLogo(): string {
  if (typeof window !== 'undefined') {
    const custom = localStorage.getItem('iepm24009_custom_logo');
    if (custom && custom.startsWith('data:image/')) return custom;
  }
  return SCHOOL_LOGO_PNG_BASE64;
}

export function getActiveSchoolLogoPath(): string {
  if (typeof window !== 'undefined') {
    const custom = localStorage.getItem('iepm24009_custom_logo');
    if (custom && custom.startsWith('data:image/')) return custom;
  }
  return SCHOOL_LOGO_PATH;
}
